var f=[0,45,90,135,180,225,270,315];var h=2.2;var a=.25;function i(t){let n=t*Math.PI/180;return{x:r(Math.sin(n)),y:r(-Math.cos(n))}}function E(t,n,o){if(!(o>0))return null;let u=n*Math.PI/180,c=Math.sin(u),s=-Math.cos(u);return{across:r((c*t.rx+s*t.ry)*o),toward:r(-(c*t.hx+s*t.hy)*o)}}function S(t){return t>0?a+(h-a)*Math.min(t,1):0}function r(t){let n=Math.round(t*1e3)/1e3;return n===0?0:n}export{i,S as n,f as r,E as t};